package com.primehr.performancemanagement.infrastructure;import com.primehr.performancemanagement.domain.PerformanceCycle;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.*;import java.util.*;
public interface PerformanceCycleRepository extends JpaRepository<PerformanceCycle,String>{Optional<PerformanceCycle>findByIdAndAgencyId(String id,String agency);Page<PerformanceCycle>findByAgencyId(String agency,Pageable pageable);boolean existsByAgencyIdAndNormalizedCode(String agency,String code);@Query("select c from PerformanceCycle c where c.agencyId=:agency and c.status<>'CANCELLED' and c.periodStart<=:to and c.periodEnd>=:from")List<PerformanceCycle>overlapping(@Param("agency")String agency,@Param("from")LocalDate from,@Param("to")LocalDate to);}
